#!/usr/bin/env bash
# ZONO — remove הערות + צפיות from the sidebar, and push.
set -euo pipefail
git am --abort 2>/dev/null || true
git fetch origin main && git checkout main && git merge --ff-only origin/main 2>/dev/null || echo "(applying onto current HEAD)"
echo "" | base64 -d > /tmp/nav-cleanup.patch
git am -3 /tmp/nav-cleanup.patch
git push origin main
echo "✅ Sidebar cleanup applied and pushed."
